param(
    [string]$DestinationPath = (Join-Path (Get-Location) 'cdt-workflow-restored'),
    [switch]$Force
)

$ErrorActionPreference = 'Stop'
$ExpectedSha256 = 'd6ca44471252e6af0a7a6753dc7f8a6521531ce61795fe0fe11c118b0005d85b'
$ExpectedFileCount = 294
$GeneratedAt = '2026-06-22T22:52:58-04:00'
$Base64Zip = @'

'@

if (Test-Path -LiteralPath $DestinationPath) {
    if (-not $Force) {
        throw "Destination already exists: $DestinationPath. Re-run with -Force to replace it."
    }

    Remove-Item -LiteralPath $DestinationPath -Recurse -Force
}

New-Item -ItemType Directory -Force -Path $DestinationPath | Out-Null
$tempZip = Join-Path ([IO.Path]::GetTempPath()) ("cdt-workflow-restore-" + [Guid]::NewGuid().ToString('N') + ".zip")
try {
    [IO.File]::WriteAllBytes($tempZip, [Convert]::FromBase64String(($Base64Zip -replace '\s', '')))
    $actualSha256 = (Get-FileHash -Algorithm SHA256 -LiteralPath $tempZip).Hash.ToLowerInvariant()
    if ($actualSha256 -ne $ExpectedSha256) {
        throw "Checksum mismatch. Expected $ExpectedSha256 but got $actualSha256."
    }

    Add-Type -AssemblyName System.IO.Compression.FileSystem
    [System.IO.Compression.ZipFile]::ExtractToDirectory($tempZip, $DestinationPath)
    $actualFileCount = (Get-ChildItem -LiteralPath $DestinationPath -Recurse -File | Measure-Object).Count
    if ($actualFileCount -ne $ExpectedFileCount) {
        throw "File count mismatch. Expected $ExpectedFileCount but restored $actualFileCount files."
    }

    Write-Host "Restored $actualFileCount files to $DestinationPath"
    Write-Host "SHA-256 verified: $ExpectedSha256"
    Write-Host "Bundle generated at: $GeneratedAt"
}
finally {
    if (Test-Path -LiteralPath $tempZip) {
        Remove-Item -LiteralPath $tempZip -Force
    }
}
